from pyspark.sql import functions as F


def old_band(value):
    # Today's step.
    return F.when(value < 5.7, "normal").when(value < 6.5, "prediabetes").otherwise("diabetes")


def new_band(value):
    # The release: no band without a real value, and results above 20 are in mmol/mol, converted to %.
    pct = F.when(value > 20, value * 0.0915 + 2.15).otherwise(value)
    return (
        F.when(F.isnan(value), None)
        .when(pct < 5.7, "normal")
        .when(pct < 6.5, "prediabetes")
        .when(pct >= 6.5, "diabetes")
    )


def solve(observations):
    # Return the HbA1c results whose band the release changes.
    return observations.select("observation_id", "value")
